interface PaymentProcessor {
    // Abstract method - must be implemented
    boolean processPayment(double amount);

    // Default method - optional to override
    default void logTransaction(double amount) {
        System.out.println("Processing: $" + amount);
    }

    default boolean validateAmount(double amount) {
        return amount > 0 && amount < 10000; // Basic validation
    }
}

class CreditCardProcessor implements PaymentProcessor {
    @Override
    public boolean processPayment(double amount) {
        if (validateAmount(amount)) { // Using default method
            logTransaction(amount); // Using default method
            return true;
        }
        return false;
    }
    // logTransaction and validateAmount inherited from interface
}

class CustomProcessor implements PaymentProcessor {
    @Override
    public boolean processPayment(double amount) {
        return amount > 0;
    }

    @Override
    public void logTransaction(double amount) { // Overriding default
        System.out.println("Custom log: " + amount);
    }
}

interface OrderRepository {
    List<Order> findAll();
    Optional<Order> findById(Long id);

    // Static factory method
    static OrderRepository inMemory() {
        return new InMemoryOrderRepository();
    }

    static OrderRepository database(String url) {
        return new DatabaseOrderRepository(url);
    }

    // Static utility method
    static boolean isValidOrderId(Long id) {
        return id != null && id > 0; // Cannot be overridden
    }
}

class InMemoryOrderRepository implements OrderRepository {
    private List<Order> orders = new ArrayList<>();

    @Override
    public List<Order> findAll() { return orders; }

    @Override
    public Optional<Order> findById(Long id) {
        return orders.stream()
            .filter(o -> o.id().equals(id))
            .findFirst();
    }
}

// Usage
var repo = OrderRepository.inMemory(); // Called on interface
boolean valid = OrderRepository.isValidOrderId(5L); // Static call

interface Notifier {
    default void send(String message) {
        System.out.println("Notifier: " + message);
    }
}

interface Logger {
    default void send(String message) {
        System.out.println("Logger: " + message);
    }
}

// This would cause compile error without override
class AlertService implements Notifier, Logger {
    @Override
    public void send(String message) {
        // Option 1: Choose one interface's default
        Notifier.super.send(message); // Call Notifier's version

        // Option 2: Combine both
        // Logger.super.send(message);
        // Notifier.super.send(message);

        // Option 3: Provide new implementation
        // System.out.println("AlertService: " + message);
    }
}

// Usage
var service = new AlertService();
service.send("System alert"); // Prints: Notifier: System alert

var orders = new ArrayList<Order>();
orders.add(new Order(1L, "Laptop", 1200.0, false));
orders.add(new Order(2L, "Mouse", 25.0, true));
orders.add(new Order(3L, "Keyboard", 80.0, false));

// forEach() - default method on Iterable
orders.forEach(order -> 
    System.out.println(order.item())
);

// removeIf() - default method on Collection
orders.removeIf(order -> order.shipped()); // Removes shipped orders

// replaceAll() - default method on List
var prices = new ArrayList<>(List.of(10.0, 20.0, 30.0));
prices.replaceAll(price -> price * 1.1); // Apply 10% increase

// stream() - default method on Collection
var total = orders.stream()
    .mapToDouble(Order::price)
    .sum();

// sort() - default method on List
orders.sort(Comparator.comparing(Order::price));

record Order(Long id, String item, double price, boolean shipped) {}

interface AuditLogger {
    void log(String message);

    default void logInfo(String message) {
        logWithLevel("INFO", message); // Calls private helper
    }

    default void logError(String message) {
        logWithLevel("ERROR", message); // Reuses same helper
    }

    default void logWarning(String message) {
        logWithLevel("WARNING", message);
    }

    // Private helper - not visible to implementing classes
    private void logWithLevel(String level, String message) {
        String timestamp = getCurrentTimestamp();
        log(String.format("[%s] %s: %s", timestamp, level, message));
    }

    // Private static helper
    private static String getCurrentTimestamp() {
        return java.time.LocalDateTime.now().toString();
    }
}

class FileAuditLogger implements AuditLogger {
    @Override
    public void log(String message) {
        System.out.println(message);
    }
    // logWithLevel and getCurrentTimestamp are NOT inherited
}
